CREATE TABLE public.business_workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() UNIQUE, name text NOT NULL DEFAULT 'Usaha Saya', data jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.business_workspaces TO authenticated; GRANT ALL ON public.business_workspaces TO service_role; ALTER TABLE public.business_workspaces ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owners manage their business" ON public.business_workspaces FOR ALL TO authenticated USING (owner_id = auth.uid()) WITH CHECK (owner_id = auth.uid());